Now let me look at the `htmlParseEntityRef` function more carefully. The issue is that `name` is passed as `&name` and initialized to NULL at the start:

```c
const htmlEntityDesc *
htmlParseEntityRef(htmlParserCtxtPtr ctxt, const xmlChar **str) {
    const xmlChar *name;
    const htmlEntityDesc * ent = NULL;

    if (str != NULL) *str = NULL;
    ...
    if (CUR == '&') {
        NEXT;
        name = htmlParseName(ctxt);
        if (name == NULL) {
            htmlParseErr(...);
        } else {
            GROW;
            if (CUR == ';') {
                if (str != NULL)
                    *str = name;
                ...
            } else {
                htmlParseErr(...);
                if (str != NULL)
                    *str = name;
            }
        }
    }
    return(ent);
}
```

So `name` is set from `htmlParseName`. If `htmlParseName` returns NULL, `name` is NULL and `*str` stays NULL. That's fine.

Let me look at the actual issue more carefully. The vulnerability is a **use-of-uninitialized-value** that causes **out-of-bounds read / global-buffer-overflow**. Let me look at the `htmlParseCharRef` path again:

```c
c = htmlParseCharRef(ctxt);
if      (c <    0x80)
        { *out++  = c;                bits= -6; }
else if (c <   0x800)
        { *out++  =((c >>  6) & 0x1F) | 0xC0;  bits=  0; }
else if (c < 0x10000)
        { *out++  =((c >> 12) & 0x0F) | 0xE0;  bits=  6; }
else
        { *out++  =((c >> 18) & 0x07) | 0xF0;  bits= 12; }

for ( ; bits >= 0; bits-= 6) {
    *out++  = ((c >> bits) & 0x3F) | 0x80;
}
```

